// @vitest-environment jsdom
/*
 * A deck shows its colours — wave 26 §D, operator: *"decks should have their
 * corresponding mana symbols."*
 *
 * ## Real decks, because the interesting cases are only in real decks
 *
 * Every deck here is one of the 96 `.dck` files under `decks/`, and every mana
 * cost comes out of the frozen pool for that deck's own era
 * (`decks/pools/standard-<date>.generated.json`, regenerated by
 * `packages/deck/src/library/build-pool-fixture.ts`). Nothing is hand-written,
 * and that is not tidiness: the two facts this fold exists to get right are
 * facts about real 2012 Standard decks.
 *
 *   - **Phyrexian mana.** CJ Steele's Infect plays Gut Shot, Mental Misstep,
 *     Apostle's Blessing and Mutagenic Growth — four cards Scryfall calls red,
 *     blue, white and green. A fold over `colors` calls that deck WURG. It has
 *     twelve Forests in it.
 *   - **A one-card splash is a colour.** Todd Anderson's UW Delver is white
 *     because of four Geists of Saint Traft and nothing else, and the fold has
 *     to see them while ignoring the Gut Shots beside them.
 *
 * A fixture invented here would have been written by whoever wrote the fold,
 * and would have agreed with it by construction.
 *
 * ## Two levels, on purpose
 *
 * `deckColorsByName` is exercised against the decklists directly — that is the
 * arm the room screen needs (§F), where a deck is a list of names. Then
 * `DeckView` and `DeckEditor` are rendered and cards are clicked INTO the
 * maindeck, which is the only way to prove the pips on screen follow the deck
 * rather than the pool: both components open with the whole pool in the
 * sideboard.
 *
 * `.test.ts` + `createElement` and the jsdom pragma on line 1, for the reasons
 * `screens/lobby.test.ts` gives.
 */

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import { afterEach, describe, expect, it } from 'vitest';
import { createElement } from 'react';
import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';

import { parseDck, type DeckFile } from '@hadoku/carddata/dck';
import { LIBRARY, deckPath, poolFixturePath, type FormatFamily, type LibraryCollection } from '@hadoku/deck/library';

import type { DraftCard } from '../draft/types.ts';
import { DeckEditor } from '../deck/DeckEditor.tsx';
import { deckFromPool, dckTextOf } from '../draft/deckFromPool.ts';

import { deckColorsByName, foldDeckColors, manaTokensOf, type DeckColor } from '@hadoku/deck';
import { DeckColors, DeckView } from './DeckView.tsx';

// A slow case's own budget, which must never undercut CI's (vitest.config.ts):
// 20 s here, 60 s on a shared CI runner where the default is already 30 s.
const SLOW_TIMEOUT = process.env.CI ? 60_000 : 20_000;

afterEach(cleanup);

/** `apps/ui/src/components` → the repo root, the way `ManaPip.test.ts` does it. */
const ROOT = resolve(import.meta.dirname ?? 'apps/ui/src/components', '..', '..', '..', '..');

const read = (repoPath: string): string => readFileSync(resolve(ROOT, repoPath), 'utf8');

/**
 * A frozen pool, as much of it as a colour fold reads.
 *
 * Declared here and parsed with `JSON.parse` rather than going through
 * `@hadoku/deck/library`'s `parsePoolFixture`, because what is under test is the
 * committed DATA: that the nine files carry the two maps, keyed the way a
 * decklist spells a card. The parser and its faults are `library.test.ts`'s, one
 * package down, and a test that read the file through it would pass on a file
 * with no maps in it at all — the parser tolerates their absence on purpose.
 */
interface FrozenPool {
  readonly date: string;
  readonly cards: readonly string[];
  readonly manaCost: Readonly<Record<string, string>>;
  readonly colors: Readonly<Record<string, string>>;
}

function fixtureFor(date: string, family: FormatFamily = 'standard'): FrozenPool {
  const raw = JSON.parse(read(poolFixturePath(date, family))) as Partial<FrozenPool>;
  const { cards, manaCost, colors } = raw;
  if (!Array.isArray(cards) || typeof manaCost !== 'object' || manaCost === null) {
    throw new Error(`${date}: the frozen pool carries no cost map`);
  }
  if (typeof colors !== 'object' || colors === null) {
    throw new Error(`${date}: the frozen pool carries no colour map`);
  }
  return { date, cards, manaCost, colors };
}

/**
 * The names one pool entry answers to: the full name, and the front face.
 *
 * `@hadoku/deck`'s `poolNameKeys` is the authority for this and is not exported
 * from the package barrel; it is two lines and its own comment explains why it
 * exists (Scryfall writes `Front // Back`, every decklist writes the front).
 */
function nameKeys(name: string): string[] {
  const cut = name.indexOf(' // ');
  return cut === -1 ? [name] : [name, name.slice(0, cut)];
}

/**
 * Every (family, date) a fixture is frozen for — the library's own eras, one
 * per collection. Keyed by (family, date) rather than date alone: wave 48 §T
 * pins Modern/Legacy eras to Standard's own dates (Settled), so two
 * collections can share a date, and deduplicating on the date alone would
 * silently skip checking one of them.
 */
const FIXTURE_KEYS = [...new Map(LIBRARY.map((c) => [`${c.family}:${c.date}`, { family: c.family, date: c.date }])).values()];

const collectionOf = (id: string): LibraryCollection => {
  const found = LIBRARY.find((c) => c.id === id);
  if (found === undefined) throw new Error(`no collection ${id}`);
  return found;
};

/** One library deck, as its file and its era's frozen pool. */
function libraryDeck(collectionId: string, file: string): { deck: DeckFile; fixture: FrozenPool } {
  const collection = collectionOf(collectionId);
  const entry = collection.decks.find((d) => d.file === file);
  if (entry === undefined) throw new Error(`no deck ${file} in ${collectionId}`);
  return { deck: parseDck(read(deckPath(collection, entry))), fixture: fixtureFor(collection.date, collection.family) };
}

const mainNames = (deck: DeckFile): string[] =>
  (deck.sections.get('main') ?? []).map((e) => e.card.name);

/** The two decks this file leans on, named once. */
const MONO_GREEN = { collection: 'power-summer-2012', file: '1-cj-steele-infect.dck' };
const UW_DELVER = { collection: 'power-summer-2012', file: '1-todd-anderson-uw-delver.dck' };

/**
 * A library deck's maindeck as a draft pool.
 *
 * The colour-bearing fields are real — `manaCost` and `colors` come straight
 * out of the frozen pool, and the set code off the `.dck` line. The rest is
 * structural filler a `DraftCard` needs and this test does not read: the
 * components sort by `manaValue` and print `typeLine`, neither of which is
 * under test here.
 */
function poolOfLibraryDeck(deck: DeckFile, fixture: FrozenPool): DraftCard[] {
  const pool: DraftCard[] = [];
  for (const entry of deck.sections.get('main') ?? []) {
    for (let copy = 0; copy < entry.count; copy++) {
      pool.push({
        cardId: `lib:${String(pool.length)}`,
        name: entry.card.name,
        manaCost: manaTokensOf(fixture.manaCost[entry.card.name] ?? ''),
        manaValue: 0,
        colors: [...(fixture.colors[entry.card.name] ?? '')] as DraftCard['colors'],
        typeLine: '',
        oracleText: '',
        setCode: entry.card.set ?? '',
        collectorNumber: '',
        rarity: 'common',
      });
    }
  }
  return pool;
}

/** The colours on screen, in the order they are drawn. */
function pipsOnScreen(): string[] {
  const box = screen.getByTestId('deck-colors');
  return [...box.querySelectorAll('[data-color]')].map((el) => el.getAttribute('data-color') ?? '');
}

/** Move one named card from the sideboard into the maindeck. */
function playCard(name: string, press: (row: HTMLElement) => void): void {
  const row = screen
    .getAllByTestId('deck-row')
    .find((el) => el.getAttribute('data-card-name') === name);
  if (row === undefined) throw new Error(`no row for ${name}`);
  press(row);
}

/* ── the data half ───────────────────────────────────────────────────── */

describe('the frozen Standard pools carry what a colour fold needs', () => {
  // Not the default 5 s: wave 48 §T grew FIXTURE_KEYS from 9 fixtures (1.2 MB)
  // to 31 (16 MB) across three families, and reading and parsing all of them is
  // 1.5 s alone on a loaded host (2026-10-16), several times that inside a full
  // `pnpm run check`.
  it('maps a cost and a colour for its own cards, under the names a decklist uses', { timeout: SLOW_TIMEOUT }, () => {
    for (const { family, date } of FIXTURE_KEYS) {
      const fixture = fixtureFor(date, family);
      const label = `${family} ${date}`;
      // Non-empty: the maps are parsed tolerantly (`pool-fixture.ts` says why),
      // so a generator that stopped emitting them would otherwise be silent.
      // The smallest pool is Type 2's 1995 summer: four sets, 886 costed cards.
      expect(Object.keys(fixture.manaCost).length, label).toBeGreaterThan(800);
      expect(Object.keys(fixture.colors).length, label).toBeGreaterThan(700);
      // Keyed exactly as `poolFromFixture` keys `legal`, which is what lets a
      // `.dck` line naming `Delver of Secrets` find
      // `Delver of Secrets // Insectile Aberration`.
      const known = new Set(fixture.cards.flatMap(nameKeys));
      // One assertion per map, naming every stray key, not one per name: 31 pools
      // of some two thousand names each made that 60,000 `expect` calls.
      expect(Object.keys(fixture.manaCost).filter((name) => !known.has(name)), `${label}: costed names no card has`).toEqual([]);
      expect(Object.keys(fixture.colors).filter((name) => !known.has(name)), `${label}: coloured names no card has`).toEqual([]);
      // A land has no cost and no colour, so it is absent rather than empty —
      // which is what keeps the two maps to the size of the spells. Measured
      // against the name keys, not the card count: a double-faced card is keyed
      // under both its names, and the Innistrad: Midnight Hunt and Crimson Vow
      // eras hold more of those than a slack of 40 over the card count covers.
      // At least 30 names go uncosted in every pool; the fewest, 42, is Type 2's
      // 1995 summer, with four sets of lands.
      expect(Object.keys(fixture.manaCost).length, label).toBeLessThan(known.size - 30);
    }
  });

  it('resolves a double-faced card by the name the decklist writes', () => {
    const { fixture } = libraryDeck(UW_DELVER.collection, UW_DELVER.file);
    expect(fixture.cards).toContain('Delver of Secrets // Insectile Aberration');
    expect(fixture.manaCost['Delver of Secrets']).toBe('{U}');
    expect(fixture.manaCost['Delver of Secrets // Insectile Aberration']).toBe('{U}');
  });

  it('carries no image field and no image URL — the names that look like one are names', () => {
    const IMAGE_FIELD = /image|img|artcrop|thumbnail|picture/i;
    const IMAGE_URL = /https?:\/\/[^"]*(\.(jpe?g|png|webp|gif)|scryfall\.io)/i;
    for (const { family, date } of FIXTURE_KEYS) {
      const label = `${family} ${date}`;
      const raw = JSON.parse(read(poolFixturePath(date, family))) as Record<string, unknown>;
      for (const key of Object.keys(raw)) expect(IMAGE_FIELD.test(key), `${label}: ${key}`).toBe(false);
      expect(IMAGE_URL.test(read(poolFixturePath(date, family))), label).toBe(false);
    }
    // Why the field check is on the TOP-LEVEL keys only: the two maps are keyed
    // by card name, and three real cards are named `Phantasmal Image`, `Twisted
    // Image` and `Grimgrin, Corpse-Born` — which `img` matches. A control that
    // cried wolf on those is the one `build-pool.ts`'s own header records
    // switching off.
    const m13 = fixtureFor('2012-07-13');
    expect(m13.manaCost['Phantasmal Image']).toBe('{1}{U}');
    expect(m13.colors['Grimgrin, Corpse-Born']).toBe('UB');
  });
});

describe("a deck's colours are a fold over its own card list", () => {
  it('reads Mono Green Infect as green, though five of its cards are not', () => {
    const { deck, fixture } = libraryDeck(MONO_GREEN.collection, MONO_GREEN.file);
    const names = mainNames(deck);
    expect(deckColorsByName(names, fixture.manaCost)).toEqual(['G']);

    // What the two easier answers would have said, so the reason this fold is
    // written the way it is cannot be deleted quietly.
    const byCardColour = (['W', 'U', 'B', 'R', 'G'] as const).filter((c) =>
      names.some((n) => (fixture.colors[n] ?? '').includes(c)),
    );
    expect(byCardColour).toEqual(['W', 'U', 'R', 'G']);
    expect(fixture.manaCost['Gut Shot']).toBe('{R/P}');
    expect(foldDeckColors(['R/P', 'U/P', 'G/P'])).toEqual([]);
  });

  it('reads UW Delver as two colours: the Geists count, the Gut Shots do not', () => {
    const { deck, fixture } = libraryDeck(UW_DELVER.collection, UW_DELVER.file);
    const names = mainNames(deck);
    expect(names).toContain('Geist of Saint Traft');
    expect(names).toContain('Gut Shot');
    expect(deckColorsByName(names, fixture.manaCost)).toEqual(['W', 'U']);
  });

  // Wave 48 §T: "MUD" (colourless artifact aggro — Lodestone Golem,
  // Metalworker, Wurmcoil Engine, Chalice of the Void, … over Ancient Tomb,
  // City of Traitors, Wasteland, Darksteel Citadel) is a recurring Legacy
  // archetype, and both times the selection chose one, EVERY spell's own
  // cost in that era's frozen pool is purely generic — checked by folding
  // every chosen deck in the library against its own fixture and listing
  // which ones read zero colours, not assumed from the archetype name; these
  // two were the only two — and doubling the library to 24 per era (2026-10-10)
  // brought three more artifact prison decks, read off the same fold.
  // Running the library forward to 2025 brought eleven more, every one a
  // colourless archetype by name and by fold: Modern's Eldrazi Tron (five
  // summers of it) and Urzatron, Legacy's Steel Stompy, 12-Post, Eldrazi
  // Post, Karn and Mystic Forge.
  // Genuinely colourless decks are real, competitive
  // Legacy archetypes, so this is a named exception, not a loosened floor —
  // a fold that broke (like the Modern GR Tron bug this same wave found,
  // which this test caught) still reads 0 for every OTHER deck and fails
  // here.
  const COLOURLESS_DECKS = new Set([
    'power-legacy-2006-3-rick-jander78-argiro-5-3',
    'power-legacy-2012-2-eric-fry-mud',
    'power-legacy-2013-1-martin-pohlmeyer-mud',
    'power-legacy-2014-1-simo-partinen-mud-post',
    'power-legacy-2016-1-demetrio-morselli-mud',
    'power-legacy-2018-1-david-salus-steel-stompy',
    'power-legacy-2020-1-nakamura-ryousuke-12-post',
    'power-legacy-2022-1-ding-hui-eldrazi-post',
    'power-legacy-2023-1-susurrus-mtg-karn',
    'power-legacy-2025-1-hiromi-kameshima-mystic-forge',
    'power-modern-2017-1-dan-musser-eldra-tron',
    'power-modern-2019-1-zachattack23-eldra-tron',
    'power-modern-2020-1-thetunnelingcat-eldra-tron',
    'power-modern-2021-1-dreamsofashiok-eldra-tron',
    'power-modern-2022-1-brady-munroe-urzatron',
    'power-modern-2022-1-damian-del-nero-eldra-tron',
  ]);

  it('gives every deck in the library at least one colour, except the real colourless ones', () => {
    // Not every deck across the library is two colours: 2008's "4c Reveillark
    // Control" (Shouhei Yamamoto) is a real four-colour deck, named for
    // exactly that, and 2013's "Human Reanimator" (Joe Lossett) genuinely
    // folds to all five — a reanimator shell splashes whatever its targets
    // cost. So the fold's ceiling is real Magic's ceiling, five; the floor is
    // one colour, except `COLOURLESS_DECKS`.
    for (const collection of LIBRARY) {
      const fixture = fixtureFor(collection.date, collection.family);
      for (const entry of collection.decks) {
        const deck = parseDck(read(deckPath(collection, entry)));
        const colors = deckColorsByName(mainNames(deck), fixture.manaCost);
        const floor = COLOURLESS_DECKS.has(entry.id) ? 0 : 1;
        expect(colors.length, entry.id).toBeGreaterThanOrEqual(floor);
        expect(colors.length, entry.id).toBeLessThanOrEqual(5);
      }
    }
  });

  it('counts a hybrid as both halves and a twobrid as its colour', () => {
    expect(foldDeckColors(manaTokensOf('{W/U}'))).toEqual(['W', 'U']);
    expect(foldDeckColors(manaTokensOf('{2/W}'))).toEqual(['W']);
    expect(foldDeckColors(manaTokensOf('{3}{X}{C}{S}'))).toEqual([]);
  });
});

/* ── the pips ────────────────────────────────────────────────────────── */

describe('the pips a deck shows', () => {
  it('draws exactly one for a mono-colour library deck', () => {
    const { deck, fixture } = libraryDeck(MONO_GREEN.collection, MONO_GREEN.file);
    const colors = deckColorsByName(mainNames(deck), fixture.manaCost);
    render(createElement(DeckColors, { colors }));
    expect(pipsOnScreen()).toEqual(['G']);
    expect(screen.getByTestId('deck-colors').getAttribute('data-colors')).toBe('G');
  });

  it('draws exactly two for a two-colour library deck', () => {
    const { deck, fixture } = libraryDeck(UW_DELVER.collection, UW_DELVER.file);
    const colors = deckColorsByName(mainNames(deck), fixture.manaCost);
    render(createElement(DeckColors, { colors }));
    expect(pipsOnScreen()).toEqual(['W', 'U']);
    expect(screen.getByTestId('deck-colors').getAttribute('data-colors')).toBe('WU');
  });

  it('says colourless rather than nothing when there is nothing to draw', () => {
    render(createElement(DeckColors, { colors: [] as DeckColor[] }));
    expect(pipsOnScreen()).toEqual([]);
    expect(screen.getByTestId('deck-colors').textContent).toBe('colourless');
  });
});

describe('DeckView follows the maindeck, not the pool', () => {
  const press = (row: HTMLElement): void => {
    fireEvent.click(within(row).getByTitle('↑'));
  };

  it("shows the colours of what has been played, as UW Delver's cards go in", () => {
    const { deck, fixture } = libraryDeck(UW_DELVER.collection, UW_DELVER.file);
    render(
      createElement(DeckView, {
        draftId: 'uw-delver-as-a-pool',
        pool: poolOfLibraryDeck(deck, fixture),
        onDownload: () => {},
      }),
    );

    // Everything opens in the sideboard, so a pool of five colours would still
    // be a deck of none.
    expect(pipsOnScreen()).toEqual([]);

    playCard('Delver of Secrets', press);
    expect(pipsOnScreen()).toEqual(['U']);

    playCard('Geist of Saint Traft', press);
    expect(pipsOnScreen()).toEqual(['W', 'U']);

    // `{R/P}`: a red card in the maindeck that the deck can cast for two life.
    playCard('Gut Shot', press);
    expect(pipsOnScreen()).toEqual(['W', 'U']);
  });

  it('counts basic lands as the colours they are', () => {
    const { deck, fixture } = libraryDeck(MONO_GREEN.collection, MONO_GREEN.file);
    render(
      createElement(DeckView, {
        draftId: 'mono-green-as-a-pool',
        pool: poolOfLibraryDeck(deck, fixture),
        onDownload: () => {},
      }),
    );
    expect(pipsOnScreen()).toEqual([]);
    fireEvent.click(screen.getByLabelText('one more Forest'));
    expect(pipsOnScreen()).toEqual(['G']);
  });
});

describe('DeckEditor shows the same colours over the same model', () => {
  /** The editor draws every card as a `CardTile`; a click on one moves it. */
  function pickCard(name: string): void {
    const tile = screen.getAllByTestId('card').find((el) => el.querySelector('.card__name')?.textContent === name);
    if (tile === undefined) throw new Error(`no card tile for ${name}`);
    fireEvent.click(tile);
  }

  it("draws the maindeck's colours as cards are clicked into it", async () => {
    const { deck, fixture } = libraryDeck(UW_DELVER.collection, UW_DELVER.file);
    render(
      createElement(DeckEditor, {
        mode: 'limited',
        draftId: 'uw-delver-as-a-pool',
        pool: poolOfLibraryDeck(deck, fixture),
        // Every card in the pool to start, so each click adds one to the deck.
        savedDeck: dckTextOf(deckFromPool('uw-delver-as-a-pool', poolOfLibraryDeck(deck, fixture))),
      }),
    );
    expect(screen.getByTestId('deck-editor')).toBeTruthy();

    expect(pipsOnScreen()).toEqual([]);
    pickCard('Delver of Secrets');
    expect(pipsOnScreen()).toEqual(['U']);
    pickCard('Geist of Saint Traft');
    expect(pipsOnScreen()).toEqual(['W', 'U']);
  });
});
